from __future__ import annotations
from typing import List, Sequence, Tuple

Matrix = Tuple[Tuple[int, ...], ...]
Poly = List[int]  # low-degree-first

def inv_mod(a: int, p: int) -> int:
    return pow(a % p, p - 2, p)

def det_mod(M: Matrix, p: int) -> int:
    n = len(M); a = [list(r) for r in M]; det = 1
    for c in range(n):
        piv = next((r for r in range(c, n) if a[r][c] % p), None)
        if piv is None: return 0
        if piv != c: a[c], a[piv] = a[piv], a[c]; det = -det
        det = (det * a[c][c]) % p; iv = inv_mod(a[c][c], p)
        for r in range(c + 1, n):
            f = (a[r][c] * iv) % p
            for k in range(c, n): a[r][k] = (a[r][k] - f * a[c][k]) % p
    return det % p

def poly_mul(a: Sequence[int], b: Sequence[int], p: int) -> Poly:
    r = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b): r[i + j] = (r[i + j] + ai * bj) % p
    return r

def poly_mod(a: Poly, m: Poly, p: int) -> Poly:
    a = [x % p for x in a]; dm = len(m) - 1; il = inv_mod(m[-1], p)
    while len(a) - 1 >= dm and any(a):
        if a[-1] == 0: a.pop(); continue
        s = len(a) - 1 - dm; f = (a[-1] * il) % p
        for i in range(len(m)): a[i + s] = (a[i + s] - f * m[i]) % p
        while a and a[-1] == 0: a.pop()
    return a or [0]

def poly_powmod(b: Poly, e: int, m: Poly, p: int) -> Poly:
    res = [1]; b = poly_mod(b, m, p)
    while e:
        if e & 1: res = poly_mod(poly_mul(res, b, p), m, p)
        b = poly_mod(poly_mul(b, b, p), m, p); e >>= 1
    return res

def poly_gcd(a: Poly, b: Poly, p: int) -> Poly:
    a = [x % p for x in a]; b = [x % p for x in b]
    def strip(z): 
        while len(z) > 1 and z[-1] == 0: z.pop()
        return z or [0]
    a, b = strip(a), strip(b)
    while any(b): a = strip(poly_mod(a, b, p)); a, b = b, a
    return strip(a)

def prime_divisors(n: int) -> List[int]:
    ds, d = [], 2
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            while n % d == 0: n //= d
        d += 1
    if n > 1: ds.append(n)
    return ds

def is_irreducible(f: Poly, p: int) -> bool:
    f = list(f)
    while f and f[-1] == 0: f.pop()
    n = len(f) - 1
    if n <= 1: return n == 1
    x = [0, 1]
    h = poly_powmod(x, p ** n, f, p)
    if poly_gcd([(h[i] if i < len(h) else 0) - (x[i] if i < 2 else 0)
                 for i in range(max(len(h), 2))], f, p) and \
       any((h[i] if i < len(h) else 0) != (x[i] if i < 2 else 0)
           for i in range(max(len(h), 2))):
        return False
    for r in prime_divisors(n):
        h = poly_powmod(x, p ** (n // r), f, p)
        sub = [(h[i] if i < len(h) else 0) - (x[i] if i < 2 else 0)
               for i in range(max(len(h), 2))]
        if len(poly_gcd(sub, f, p)) - 1 != 0: return False
    return True

def char_poly(M: Matrix, p: int) -> Poly:
    n = len(M); xs = list(range(n + 1)); ys = []
    for x in xs:
        A = tuple(tuple((x if i == j else 0) - M[i][j] for j in range(n))
                  for i in range(n))
        ys.append(det_mod(A, p))
    co = [0] * (n + 1)
    for i in range(len(xs)):
        num, den = [1], 1
        for j in range(len(xs)):
            if j == i: continue
            num = poly_mul(num, [(-xs[j]) % p, 1], p)
            den = (den * (xs[i] - xs[j])) % p
        sc = (ys[i] * inv_mod(den, p)) % p
        for d2, cv in enumerate(num):
            if d2 <= n: co[d2] = (co[d2] + sc * cv) % p
    return co

def verify_certificate(M: Matrix, p: int) -> bool:
    if det_mod(M, p) == 0: return False
    return is_irreducible(char_poly(M, p), p)

from __future__ import annotations
from itertools import product
from typing import Tuple

def mu(m: int) -> int:
    if m == 1: return 1
    res, d, x = 1, 2, m
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0: x //= d; e += 1
            if e > 1: return 0
            res = -res
        d += 1
    if x > 1: res = -res
    return res

def num_irreducible_monic(n: int, q: int) -> int:
    return sum(mu(d) * q ** (n // d) for d in range(1, n + 1)
               if n % d == 0) // n

def gl_order(n: int, q: int) -> int:
    prod = 1
    for k in range(n): prod *= (q ** n - q ** k)
    return prod

def closed_form_density(n: int, q: int) -> float:
    irr = num_irreducible_monic(n, q)
    certified = irr * gl_order(n, q) // (q ** n - 1)
    return certified / gl_order(n, q)

# Exact enumeration (requires verify_certificate from the verification
# algorithm) for small (n, q):
def exact_density(n: int, p: int, verify) -> Tuple[int, int]:
    total = certified = 0
    for ent in product(range(p), repeat=n * n):
        M = tuple(tuple(ent[i * n + j] for j in range(n))
                  for i in range(n))
        if not verify.__globals__['det_mod'](M, p): continue
        total += 1
        if verify(M, p): certified += 1
    return certified, total

from __future__ import annotations
from itertools import product
from typing import List, Optional, Tuple

Matrix = Tuple[Tuple[int, ...], ...]
Vector = Tuple[int, ...]

def inv_mod(a: int, p: int) -> int:
    return pow(a % p, p - 2, p)

def mat_vec(M: Matrix, v: Vector, p: int) -> Vector:
    n = len(M)
    return tuple(sum(M[i][j] * v[j] for j in range(n)) % p
                 for i in range(n))

def rank_mod(rows: List[Vector], p: int) -> int:
    a = [list(r) for r in rows]
    if not a: return 0
    ncol = len(a[0]); r = 0
    for col in range(ncol):
        piv = next((i for i in range(r, len(a)) if a[i][col] % p), None)
        if piv is None: continue
        a[r], a[piv] = a[piv], a[r]
        iv = inv_mod(a[r][col], p); a[r] = [(x * iv) % p for x in a[r]]
        for i in range(len(a)):
            if i != r and a[i][col] % p:
                f = a[i][col]
                a[i] = [(a[i][c] - f * a[r][c]) % p for c in range(ncol)]
        r += 1
        if r == len(a): break
    return r

def orbit_rank(M: Matrix, v: Vector, p: int) -> int:
    n = len(M); vecs = []; cur = v
    for _ in range(n + 1):
        vecs.append(cur); cur = mat_vec(M, cur, p)
    return rank_mod(vecs, p)

def has_proper_invariant_subspace(M: Matrix, p: int
                                  ) -> Tuple[bool, Optional[Vector]]:
    n = len(M)
    for v in product(range(p), repeat=n):
        if any(v) and orbit_rank(M, v, p) < n:
            return True, v
    return False, None
